import React from 'react';
import Typography from '@mui/material/Typography';
import Paper from '@mui/material/Paper';
import Stack from '@mui/material/Stack';

interface NextObjectiveDisplayProps {
  nextLocationHint: string | null;
  distanceToNextObjective: number | null;
  isGameCompleted: boolean;
}

const NextObjectiveDisplay: React.FC<NextObjectiveDisplayProps> = ({ nextLocationHint, distanceToNextObjective, isGameCompleted }) => {
  return (
    <Paper elevation={2} sx={{ p: 2, mt: 2, backgroundColor: isGameCompleted ? 'success.light' : 'info.light' }}>
      {isGameCompleted ? (
        <Typography variant="h6" align="center" sx={{ color: 'success.contrastText', py: 1 }}>
          {nextLocationHint || 'ゲームクリアです！'}
        </Typography>
      ) : (
        <Stack spacing={1} alignItems="center" sx={{ py: 1 }}>
          <Typography variant="body1" component="p" align="center" sx={{ color: 'info.contrastText' }}>
            次の場所: {nextLocationHint}
          </Typography>
          {distanceToNextObjective !== null && (
            <Typography variant="h6" color="info.contrastText" align="center">
              現在地からの距離: {distanceToNextObjective.toFixed(1)} m
            </Typography>
          )}
        </Stack>
      )}
    </Paper>
  );
};

export default NextObjectiveDisplay;