import React from 'react';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import Paper from '@mui/material/Paper';
import { QuizQuestion } from '../quizData'; // Assuming QuizQuestion is exported from quizData
import { locations } from '../locationsData'; // Import locations data

interface StartQuizButtonProps {
  currentQuestion: QuizQuestion;
  onStartQuiz: () => void;
}

const getLocationNameById = (locationId: number): string => {
    const location = locations.find(loc => loc.id === locationId);
    return location ? location.name : '不明な場所';
};

const StartQuizButton: React.FC<StartQuizButtonProps> = ({ currentQuestion, onStartQuiz }) => {
  return (
    <Paper elevation={3} sx={{ p: { xs: 2, sm: 3 }, mt: 2, backgroundColor: 'secondary.light' }}>
      <Typography variant="h6" gutterBottom sx={{ color: 'secondary.contrastText' }}>
        {getLocationNameById(currentQuestion.locationId)} が近くにあります！
      </Typography>
      <Button onClick={onStartQuiz} variant="contained" color="primary" size="large" sx={{ mt: 1 }}>
        謎解きを開始する
      </Button>
    </Paper>
  );
};

export default StartQuizButton;