import React from 'react';
import Typography from '@mui/material/Typography';
import Button from '@mui/material/Button';
import Box from '@mui/material/Box';

interface GameStatusDisplayProps {
  difficultyLevel: 'elementary' | 'junior_high' | 'high_school' | null;
  onResetGame: () => void;
}

const GameStatusDisplay: React.FC<GameStatusDisplayProps> = ({ difficultyLevel, onResetGame }) => {
  return (
    <>
      {difficultyLevel && (
        <Typography variant="h6" align="center" sx={{ mt: 4, mb: 1.5 }}>
          選択中の難易度: <Box component="span" sx={{ fontWeight: 'bold' }}>
            {difficultyLevel === 'elementary' ? '小学生' : difficultyLevel === 'junior_high' ? '中学生' : '高校生'}
          </Box>
        </Typography>
      )}
      <Box sx={{ textAlign: 'center', mt: difficultyLevel ? 1.5 : 4, mb: 2 }}>
        <Button onClick={onResetGame} variant="contained" color="error" size="large">
          ゲームをリセットする
        </Button>
      </Box>
    </>
  );
};

export default GameStatusDisplay;